<?php
use App\Actions\Donations\SaveDonation; use App\DonationPaymentMethod; use App\DonationPaymentStatus; use App\DonationSource; use App\DonorType; use App\Models\Donation; use App\Models\DonationCampaign; use App\Models\DonationCategory; use App\Models\Donor; use App\RecurringFrequency; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Gate; use Illuminate\Validation\Rule; use Livewire\Attributes\Title; use Livewire\Component;
new #[Title('Add Donation')] class extends Component { public ?int $donorId=null; public bool $newDonor=false; public bool $anonymous=false; public string $firstName=''; public string $lastName=''; public string $email=''; public string $phone=''; public string $donorType='visitor'; public string $categoryId=''; public string $campaignId=''; public string $amount=''; public string $currency='USD'; public string $method='cash'; public string $status='pending'; public string $source='admin_entry'; public string $donatedAt=''; public string $provider=''; public string $providerReference=''; public string $transactionReference=''; public string $notes=''; public string $internalNotes=''; public bool $recurring=false; public string $frequency='';
 public function mount():void{Gate::authorize('create',Donation::class);$this->donatedAt=now()->format('Y-m-d\TH:i');$this->currency=(string)app(\App\Settings\SettingManager::class)->get('localization','default_currency','USD');}
 public function save(SaveDonation $save):void{$data=$this->validate(['donorId'=>['nullable','exists:donors,id'],'firstName'=>[Rule::requiredIf($this->newDonor&&!$this->anonymous),'nullable','string','max:100'],'lastName'=>['nullable','string','max:100'],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:50'],'donorType'=>['required',Rule::enum(DonorType::class)],'categoryId'=>['required','exists:donation_categories,id'],'campaignId'=>['nullable','exists:donation_campaigns,id'],'amount'=>['required','numeric','gt:0'],'currency'=>['required','alpha','size:3'],'method'=>['required',Rule::enum(DonationPaymentMethod::class)],'status'=>['required',Rule::enum(DonationPaymentStatus::class)],'source'=>['required',Rule::enum(DonationSource::class)],'donatedAt'=>['required','date'],'provider'=>['nullable','string','max:100'],'providerReference'=>['nullable','string','max:255','unique:donations,provider_reference'],'transactionReference'=>['nullable','string','max:255'],'notes'=>['nullable','string','max:5000'],'internalNotes'=>['nullable','string','max:5000'],'frequency'=>[Rule::requiredIf($this->recurring),'nullable',Rule::enum(RecurringFrequency::class)]]);$donorId=$this->anonymous?null:$this->donorId;if(!$donorId&&$this->newDonor&&!$this->anonymous){Gate::authorize('create',Donor::class);$donor=Donor::create(['first_name'=>$data['firstName'],'last_name'=>$data['lastName'],'email'=>$data['email']?:null,'phone'=>$data['phone']?:null,'donor_type'=>$data['donorType'],'is_anonymous'=>false]);$donorId=$donor->id;}$donation=$save->handle(Auth::user(),['donor_id'=>$donorId,'donation_category_id'=>$data['categoryId'],'donation_campaign_id'=>$data['campaignId']?:null,'amount'=>$data['amount'],'currency'=>strtoupper($data['currency']),'payment_method'=>$data['method'],'payment_status'=>$data['status'],'payment_provider'=>$data['provider']?:null,'provider_reference'=>$data['providerReference']?:null,'transaction_reference'=>$data['transactionReference']?:null,'