 public function donors(){return Donor::orderBy('first_name')->limit(200)->get();} public function categories(){return DonationCategory::where('is_active',true)->orderBy('name')->get();} public function campaigns(){return DonationCampaign::where('status','active')->when($this->categoryId,fn($q)=>$q->where(fn($q)=>$q->whereNull('donation_category_id')->orWhere('donation_category_id',$this->categoryId)))->orderBy('name')->get();}
