<div class="mx-auto w-full max-w-5xl space-y-6"><x-admin.page-header :title="__('Add donation')" :description="__('Record a manual donation or payment notification.')" :eyebrow="__('Giving management')"/><form wire:submit="save" class="space-y-6"><section class="space-y-4 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading size="lg">{{__('Donor')}}</flux:heading><div class="flex gap-5"><flux:checkbox wire:model.live="anonymous" :label="__('Anonymous donation')"/><flux:checkbox wire:model.live="newDonor" :label="__('Create donor profile')"/></div>@unless($anonymous)@if($newDonor)<div class="grid gap-4 sm:grid-cols-2"><flux:input wire:model="firstName" :label="__('First name')"/><flux:input wire:model="lastName" :label="__('Last name')"/><flux:input wire:model="email" type="email" :label="__('Email')"/><flux:input wire:model="phone" :label="__('Phone')"/><flux:select wire:model="donorType" :label="__('Donor type')">@foreach(DonorType::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select></div>@else<flux:select wire:model="donorId" :label="__('Existing donor')"><flux:select.option value="">{{__('No donor profile')}}</flux:select.option>@foreach($this->donors() as $x)<flux:select.option :value="$x->id">{{$x->full_name}} — {{$x->email}}</flux:select.option>@endforeach</flux:select>@endif@endunless</section>
<section class="space-y-4 rounded-xl border bg-white p-6 dark:border-zinc-800 dark:bg-zinc-900"><flux:heading size="lg">{{__('Donation and payment')}}</flux:heading><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><flux:select wire:model.live="categoryId" :label="__('Category')"><flux:select.option value="">{{__('Choose')}}</flux:select.option>@foreach($this->categories() as $x)<flux:select.option :value="$x->id">{{$x->name}}</flux:select.option>@endforeach</flux:select><flux:select wire:model="campaignId" :label="__('Campaign')"><flux:select.option value="">{{__('None')}}</flux:select.option>@foreach($this->campaigns() as $x)<flux:select.option :value="$x->id">{{$x->name}}</flux:select.option>@endforeach</flux:select><flux:input wire:model="amount" type="number" step="0.01" min="0.01" :label="__('Amount')"/><flux:input wire:model="currency" maxlength="3" :label="__('Currency')"/><flux:input wire:model="donatedAt" type="datetime-local" :label="__('Donation date')"/><flux:select wire:model="source" :label="__('Source')">@foreach(DonationSource::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:select wire:model="method" :label="__('Payment method')">@foreach(DonationPaymentMethod::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:select wire:model="status" :label="__('Status')">@foreach(DonationPaymentStatus::cases() as $x)<flux:select.option :value="$x->value">{{$x->label()}}</flux:select.option>@endforeach</flux:select><flux:input wire:model="provider" :label="__('Provider')"/><flux:input wire:model="providerReference" :label="__('Provider reference')"/><flux:input wire:model="transactionReference" :label="__('Transaction reference')"/></div><flux:checkbox wire:model.live="recurring" :label="__('Recurring pledge (informational only)')"/>@if($recurring)<flux:select wire:model="frequency" :label="__('Frequency')">@foreach(Re